// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256[] memory v) public {
        // Ensure length match and non-empty as required
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length == v.length);
        // Preclude precompiles and the contract under test itself as caddress to avoid unexpected reverts
        vm.assume(caddress != address(c));
        vm.assume(caddress != address(0));
        // Ensure 'from' is not the zero address to avoid potential ERC20 transferFrom reverts
        vm.assume(from != address(0));

        // Attempt the transfer, capturing success and return value
        (bool ok, bytes memory ret) = c.call(abi.encodeWithSignature("transfer(address,address,address[],uint256[])", from, caddress, _tos, v));

        if (ok) {
            // If the call did not revert, the return value must be true
            bool returned = abi.decode(ret, (bool));
            assertTrue(returned);
        }
    }
}
